// ── parsing ────────────────────────────────────────────────────────────────────────────────────────────────────────
export type Fn = { id: string; label: string; generic: RegExp | null; genericNot: RegExp | null };
export type Spec = { id: string; fn: string; label: string; title: RegExp | null; not: RegExp | null; sig: string[]; near: Record<string, number> };
const rx = (src: string): { yes: RegExp | null; no: RegExp | null } => {
  const s = src.trim(); if (!s) return { yes: null, no: null };
  // "!" outside a character class or group starts the exclusion
  let depth = 0, cut = -1;
  for (let i = 0; i < s.length; i++) { const c = s[i]; if (c === "\\") { i++; continue; } if (c === "(" || c === "[") depth++; else if (c === ")" || c === "]") depth--; else if (c === "!" && depth === 0) { cut = i; break; } }
  const yes = cut < 0 ? s : s.slice(0, cut), no = cut < 0 ? "" : s.slice(cut + 1);
  // a word edge that also holds beside ".net", "c#", "c++": no letter or digit on that side
  const edge = (x: string) => x.replace(/\\b/g, (_m, i: number) => (/[)\]a-z0-9#?+]/i.test(x[i - 1] ?? "") ? "(?![a-z0-9])" : "(?<![a-z0-9])"));
  return { yes: yes ? new RegExp(edge(yes), "i") : null, no: no ? new RegExp(edge(`\\b(${no})`), "i") : null };
};
function parse(): { fns: Fn[]; specs: Spec[] } {
  const fns: Fn[] = [], specs: Spec[] = [];
  for (const raw of SOURCE.split("\n")) {
    const line = raw.trim(); if (!line) continue;
    if (line.startsWith("#")) {
      const [id, label, generic] = line.slice(1).split(" | ").map((x) => x.trim()); const r = rx(generic ?? "");
      fns.push({ id, label, generic: r.yes, genericNot: r.no }); continue;
    }
    const [id, label, title, sig, near] = line.split(" | ").map((x) => (x ?? "").trim()); const r = rx(title ?? "");
    const fn = id.split(".")[0] === "research" ? "data" : id.split(".")[0] === "presales" ? "sales" : id.split(".")[0] === "biz" ? "ops" : id.split(".")[0];
    const nb: Record<string, number> = {};
    for (const p of (near ?? "").split(/\s+/).filter(Boolean)) { const [k, w] = p.split(":"); nb[k] = Number(w); }
    specs.push({ id, fn, label, title: r.yes, not: r.no, sig: (sig ?? "").split(",").map((x) => x.trim().toLowerCase()).filter(Boolean), near: nb });
  }
  return { fns, specs };
}
export const { fns: FUNCTIONS, specs: SPECS } = parse();
export const SPEC = new Map(SPECS.map((s) => [s.id, s]));
export const FN = new Map(FUNCTIONS.map((f) => [f.id, f]));

/** How readily someone in specialisation `a` can do the work of `b`, 0–1: the same is 1, a listed neighbour its weight
 *  (whichever direction is listed, the larger), the same function otherwise 0.2, anything else 0. */
export function transfer(a: string, b: string): number {
  if (a === b) return 1;
  const x = SPEC.get(a), y = SPEC.get(b); if (!x || !y) return 0;
  const w = Math.max(x.near[b] ?? 0, y.near[a] ?? 0);
  if (w) return w;
  return x.fn === y.fn ? 0.2 : 0;
}

// ── fields: the industry a posting or a résumé sits in. A preference, never a screen. ─────────────────────────────────
export const FIELDS: { id: string; label: string; sig: RegExp }[] = [
  { id: "bfsi", label: "Banking, financial services and insurance", sig: /\b(bank(ing)?|nbfc|lending|loans?|insurance|wealth|capital markets|payments|fintech|mutual funds?|brokerage|credit cards?)\b/gi },
  { id: "health", label: "Healthcare, pharma and life sciences", sig: /\b(hospital|pharma(ceutical)?|clinical|patients?|healthcare|life sciences|medical devices?|biotech|diagnostics)\b/gi },
  { id: "retail", label: "Retail, e-commerce and consumer goods", sig: /\b(retail|e-?commerce|consumer goods|fmcg|cpg|marketplace|d2c|grocery|fashion|quick commerce)\b/gi },
  { id: "auto", label: "Automotive and mobility", sig: /\b(automotive|vehicles?|oem|ev\b|electric vehicles?|adas|autosar|mobility|two-wheeler)\b/gi },
  { id: "semi", label: "Semiconductors and electronics", sig: /\b(semiconductors?|silicon|asic|soc|chips?|vlsi|electronics)\b/gi },
  { id: "telecom", label: "Telecom and networking", sig: /\b(telecom|5g|lte|network operators?|isp|wireless carriers?)\b/gi },
  { id: "energy", label: "Energy, utilities and industrial", sig: /\b(oil and gas|energy|utilities|power plant|renewables?|petroleum|chemicals|industrial|manufacturing plant)\b/gi },
  { id: "saas", label: "Software products and SaaS", sig: /\b(saas|b2b software|product company|software products?|platform company|startup)\b/gi },
  { id: "services", label: "IT services and consulting", sig: /\b(clients?'? (projects?|engagements?)|consulting firm|it services|service delivery|offshore|onsite)\b/gi },
  { id: "edu", label: "Education", sig: /\b(edtech|education|school|university|learners?|students?)\b/gi },
  { id: "hosp", label: "Hospitality and travel", sig: /\b(hotel|hospitality|travel|airline|resort|restaurant)\b/gi },
];
export function fieldsOf(text: string): { id: string; n: number }[] {
  const t = text.slice(0, 15000);
  return FIELDS.map((f) => ({ id: f.id, n: (t.match(f.sig) ?? []).length })).filter((x) => x.n >= 2).sort((a, b) => b.n - a.n);
}
